from pathlib import Path
import hashlib,json,zipfile,copy,datetime
R=Path.cwd();B=R/'docs/art/armor-draco-whole-20261112';P=R/'docs/art/armor-tyr-whole-20261112'
def read(p):return json.loads(Path(p).read_text())
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def ref(p):return {'path':str(p),'sha256':sha(p)}
def write(n,v):
 p=B/n
 if p.exists():
  assert read(p)==v, 'existing partial evidence differs'
  return ref(p)
 p.write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n');return ref(p)
now=datetime.datetime.now(datetime.timezone.utc).isoformat();key='forbidden_arcanus:draco_arcanus';prov=read(B/'provenance.json');ctx=read(B/'context-provenance.json')
for rec,prefix in [(prov,B/'source'),(ctx,B/'context')]:
 assert sha(rec['archive'])==rec['archive_sha256']
 with zipfile.ZipFile(rec['archive']) as z:
  for n,h in rec['entries'].items():assert sha(prefix/n)==h==hashlib.sha256(z.read(rec.get('root','')+n)).hexdigest(),n
base=read(R/'docs/art/armor-ars-reference-20261111/source-baseline.json');assert len(base)==289
for n,h in base.items():assert sha(R/n)==h,n
